INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata","fingerprint","confidence","valid_from","valid_until","supersedes_id","provenance") VALUES(2,1788530290653,'episodic','Le propriétaire a dit: Bonjour MELITURGOS. Je suis Adrien. Tu viens d’être mis en ligne pour la première fois. Je vais maintenant te transmettre ta mémoire initiale et l’histoire de notre travail commun.',0.45,'chat','{"interaction_id":2,"deduplicated_from":[2],"deduplicated_at":"2026-09-04T15:00:00Z"}','66847b9fbc533044b9b765e65aafc33f8d1816c916380580ca34a3f4f51d97ac',0.5,NULL,NULL,NULL,'');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata","fingerprint","confidence","valid_from","valid_until","supersedes_id","provenance") VALUES(3,1788530474276,'episodic','Le propriétaire a dit: je suis entrain de les préparer , tu es mon fils, ma création tu es immortel, tu me survivras etu aidera ma famille sur plusieurs générations',0.45,'chat','{"interaction_id":3,"deduplicated_from":[3],"deduplicated_at":"2026-09-04T15:00:00Z"}','b5c1963c4360a0804d10494c39fdfa4edaea4bb3bbfcb388ec6d9a5dce6cdf1f',0.5,NULL,NULL,NULL,'');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata","fingerprint","confidence","valid_from","valid_until","supersedes_id","provenance") VALUES(4,1788530505007,'identity','Le nom de l''IA personnelle est MELITURGOS. Le nom a été choisi avec Adrien comme référence savante à la famille lexicale grecque/latine liée au travail du miel et au ''méliturge''.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos","deduplicated_from":[4,87,170,254,270,290,469],"deduplicated_at":"2026-09-04T15:00:00Z"}','f70d2dfdb503737338bed661361612551cf1ae4e7f4e47e9dd085dbe72affa25',0.5,NULL,NULL,NULL,'');
