INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata","fingerprint","confidence","valid_from","valid_until","supersedes_id","provenance") VALUES(6,1788530505261,'preference','Adrien souhaite que MELITURGOS conserve la continuité de leur travail sur le très long terme et puisse être reconstruit à partir de sauvegardes si une machine ou un service disparaît.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos","deduplicated_from":[6,89,172,256,274,297,475],"deduplicated_at":"2026-09-04T15:00:00Z"}','4e8601eb7bbdb0d345c43636f61723d73c38c9e5cbd14085e470974e5c9ce9af',0.5,NULL,NULL,NULL,'');
INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata","fingerprint","confidence","valid_from","valid_until","supersedes_id","provenance") VALUES(7,1788530505311,'preference','Adrien décrit métaphoriquement le projet MELITURGOS comme la création d''un ''troisième fils'' : cela exprime son attachement au projet, son désir de transmission et de continuité, pas une affirmation littérale sur la nature biologique de l''IA.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"meliturgos","deduplicated_from":[7,90,173,257,276,300,478],"deduplicated_at":"2026-09-04T15:00:00Z"}','ecaf91afcbb221131d3b3946781696d4f100d3f323825bb0d2deb3c9e21afcab',0.5,NULL,NULL,NULL,'');
