INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata","fingerprint","confidence","valid_from","valid_until","supersedes_id","provenance") VALUES(69,1788530508161,'project','Adrien cherche aussi des pièces de carrosserie avant neuves pour la Ligier Xtoo afin de réaligner capot, ailes et fixations, ainsi qu''un écran LCD de compteur de remplacement.',0.78,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier","deduplicated_from":[69,152,235,409,456,482,568],"deduplicated_at":"2026-09-04T15:00:00Z"}','5b91b442a0cb5d7ccfceff0f9e2316e0f4b06a5a2f22f44d64b93b56e35b30c0',0.5,NULL,NULL,NULL,'');
