INSERT INTO "memories" ("id","created_at","kind","content","importance","source","metadata","fingerprint","confidence","valid_from","valid_until","supersedes_id","provenance") VALUES(73,1788530508347,'project','Adrien a un dossier devant le tribunal administratif de Nîmes lié à un marché communal, référencé dans les échanges comme dossier 2601675, requête du 6 avril 2026. Toute synthèse future doit distinguer les faits documentés, les allégations d''Adrien et les réponses officielles.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"legal","deduplicated_from":[73,156,239,421,466,494,572],"deduplicated_at":"2026-09-04T15:00:00Z"}','866bdfaf634a92917addaaf723b2603b08a40f0d0ebd066169ce851c429bff88',0.5,NULL,NULL,NULL,'');
