INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(268,1788530567751,'project','Le 4 septembre 2026, MELITURGOS a d''abord été préparé en v0.1 locale Windows avec Python, Ollama, Qwen3 4B, Flask, SQLite, mémoire locale, feedback 👍/👎 et registre de modules.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_history","date":"2026-09-04"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(269,1788530567800,'decision','Le PC d''Adrien a planté pendant l''installation locale. La décision a été prise de déplacer le cœur de MELITURGOS en ligne pour ne plus dépendre de l''allumage du PC.',0.97,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_history","date":"2026-09-04"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(270,1788530567875,'identity','Le nom de l''IA personnelle est MELITURGOS. Le nom a été choisi avec Adrien comme référence savante à la famille lexicale grecque/latine liée au travail du miel et au ''méliturge''.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(271,1788530567848,'project','MELITURGOS Cloud v0.2.1 a été déployé sur Cloudflare Workers le 4 septembre 2026.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud","date":"2026-09-04"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(272,1788530567935,'identity','MELITURGOS est conçu comme une IA personnelle persistante liée à Adrien, avec sa propre mémoire, son historique de travail, ses compétences et une continuité indépendante du modèle de langage utilisé comme moteur.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(273,1788530567897,'fact','L''URL de travail Cloudflare de MELITURGOS est meliturgos.adrien-lopezcarreras.workers.dev.',0.96,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(274,1788530567978,'preference','Adrien souhaite que MELITURGOS conserve la continuité de leur travail sur le très long terme et puisse être reconstruit à partir de sauvegardes si une machine ou un service disparaît.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(275,1788530567946,'fact','La mémoire persistante de MELITURGOS Cloud utilise une base Cloudflare D1 nommée ''meliturgos-memory'', reliée au Worker par le binding DB.',0.99,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(276,1788530568024,'preference','Adrien décrit métaphoriquement le projet MELITURGOS comme la création d''un ''troisième fils'' : cela exprime son attachement au projet, son désir de transmission et de continuité, pas une affirmation littérale sur la nature biologique de l''IA.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"meliturgos"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(277,1788530567990,'fact','Le cerveau cloud de MELITURGOS utilise Cloudflare Workers AI via un binding nommé AI.',0.99,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(278,1788530568072,'decision','La priorité architecturale de MELITURGOS est de séparer identité/mémoire/compétences du modèle de base afin de pouvoir remplacer le moteur par un meilleur modèle sans perdre l''histoire acquise.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"architecture"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(279,1788530568039,'fact','Le modèle par défaut prévu dans MELITURGOS Cloud v0.2.1 est @cf/zai-org/glm-4.7-flash, avec des modèles alternatifs configurés dans l''interface.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"meliturgos_cloud"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(280,1788530568122,'lesson','MELITURGOS doit distinguer les faits, les hypothèses, les anciennes propositions et les corrections explicites d''Adrien. Une ancienne réponse d''assistant ne doit jamais devenir automatiquement une vérité.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"epistemology"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(281,1788530568085,'lesson','L''accès web de MELITURGOS Cloud est protégé par authentification. Le secret de mot de passe ne doit jamais être stocké dans GENESIS, dans les conversations ou dans les sauvegardes en clair.',1,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"security"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(282,1788530568167,'preference','Adrien préfère des réponses détaillées, concrètes, directement exploitables et orientées vers l''action.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"working_style"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(283,1788530568136,'decision','La mémoire de MELITURGOS doit être sauvegardée régulièrement sous forme exportable (JSON/JSONL/SQLite/texte), avec plusieurs copies chiffrées et une procédure de restauration documentée.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"backup"}');
