INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(285,1788530568192,'project','Un objectif futur est de créer une archive ''GENESIS'' autonome contenant identité, mémoire, chronologie, compétences, code source, registre de modèles, checksums et procédure RESTORE_ME.',0.92,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"backup"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(286,1788530568259,'preference','Adrien ne code pas et ne souhaite pas être obligé de gérer des détails techniques complexes ; les outils doivent être simples à lancer et à utiliser.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"working_style"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(287,1788530568245,'decision','Un futur nœud local pourra redevenir un calculateur optionnel quand le PC fonctionne, tandis que le cœur cloud restera accessible 24/7.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"architecture"}');
