INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(374,1788530570019,'fact','Le site Vérité Interdite a un hébergement OVH Web Cloud STARTER mutualisé, insuffisant pour faire tourner le cerveau de MELITURGOS mais utile pour des sites, sous-domaines ou interfaces légères.',0.87,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"web"}');
