INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(387,1788530570348,'preference','Adrien veut que l''autobiographie vérifie qu''aucune source documentaire pertinente n''a été oubliée avant de considérer le travail complet.',0.84,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"autobiography"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(388,1788530570360,'project','Lemlist a été utilisé pour la prospection commerciale ; Adrien souhaite automatiser autant que possible la prospection, les relances et la recherche de prospects sans dépenses inutiles.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"prospecting"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(389,1788530570387,'fact','Le produit GMS a été mis en rayon à U Express Calvisson le 9 juillet 2026. Une commande de 50 pots à 5,00 € HT a été facturée le 11 juillet 2026, avec reprise des invendus à un mois.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS","date":"2026-07-11"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(390,1788530570402,'project','Adrien développe aussi un roman de science-fiction dystopique, avec un monde couvert à 100 %, IA omniprésente, caste de maintenance sur la Lune et migrations économiques/climatiques. Un titre proposé a été ''Orphelin du code''.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"publishing"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(391,1788530570417,'project','Adrien est lié au projet apicole et alimentaire ''Atelier du Méliturge''. La société est une SASU créée fin 2025 ; Danielle Lopez en est présidente et Adrien directeur général.',0.95,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"atelier_du_meliturge"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(392,1788530570444,'fact','Le prix public demandé pour le pot GMS était 6,50 € TTC ; une hypothèse de nouvelle commande a été envisagée à 5,50 € HT.',0.78,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(393,1788530570477,'fact','L''objet de l''Atelier du Méliturge couvre notamment miel, gelée royale, pâtes à tartiner, barres, shots et bougies.',0.84,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"atelier_du_meliturge"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(394,1788530570468,'fact','Adrien a travaillé ou candidaté sur des plateformes de tâches IA/données telles qu''Outlier, Multimango, OneForma et Appen.',0.76,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"work_platforms"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(395,1788530570490,'fact','La production du produit GMS passe par l''ESAT des Chênes Verts avec MOQ de 80 pots, DDM 3 mois et délai d''environ une semaine.',0.85,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(396,1788530570543,'fact','Adrien a une activité apicole en micro-BA, cotisant solidaire, avec conversion BIO engagée en 2023.',0.8,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"apiculture"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(397,1788530570556,'fact','Sur OneForma, un problème a été rencontré sur le job 13856 : la page d''application s''affichait puis disparaissait et le bouton Apply était grisé.',0.65,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"work_platforms"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(398,1788530570560,'lesson','Après dégustation, le retour a été mitigé et le magasin a demandé un pot lisse et un packaging plus travaillé.',0.83,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"GMS"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(399,1788530570588,'fact','Le rucher 2026 a commencé avec environ 30 ruches, mais au 1er août 2026 seules les ruches 1, 6 et 8 étaient encore vivantes selon le suivi partagé ; la production de gelée royale 2026 a été nulle ou fortement compromise.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"apiculture","date":"2026-08-01"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(400,1788530570602,'preference','Pour ses activités de travail, Adrien préfère des missions avec peu d''interactions complexes et évite autant que possible les rôles impliquant réglementation ou contestation juridique délicate.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"work"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(401,1788530570629,'project','Adrien a aussi travaillé sur des miels infusés/gourmands avec sourcing local : verveine, menthe, ortie, romarin, feuilles d''olivier, gaillet gratteron, lavande, thym, fenouil, gingembre séché.',0.72,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"products"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(402,1788530570656,'preference','Pour le carnet de rucher 2026, Adrien veut un document professionnel, très détaillé, imprimable, sans observations inutiles et fidèle aux faits opérationnels.',0.85,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"apiculture"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(403,1788530570671,'project','Adrien possède une Ligier Xtoo, généralement décrite dans les échanges comme une Xtoo 2009, et mène plusieurs réparations mécaniques et esthétiques.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(404,1788530570697,'preference','Dans les recettes de miels infusés/gourmands, Adrien a demandé d''éviter la lavande seule et le thym seul ; l''association menthe + romarin a été validée.',0.76,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"products"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(405,1788530570724,'decision','Le planning hebdomadaire du Rucher du Méliturge doit prioriser récoltes de gelée royale, greffage, nourrissement, contrôle des reines/colonies et tâches du site, avec indisponibilités récurrentes mardi matin, vendredi matin, samedi et dimanche.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"apiculture"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(406,1788530570743,'fact','Des réparations de la Ligier ont inclus démarreur, cardan avant droit, deux supports moteur et capteur de pression d''huile. Restent ou ont été évoqués : biellettes de direction gauche/droite, soufflets et bougies de préchauffage.',0.76,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(407,1788530570768,'project','La parcelle Y31 à Calvisson fait partie des projets d''installation du rucher. Un comodat d''un an renouvelable a été signé le 19 juillet 2026, avec limite de 50 ruches et sans constructions dures.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31","date":"2026-07-19"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(408,1788530570764,'project','Adrien a envisagé puis organisé l''arrêt de ses marchés et la cession de ses emplacements de Nîmes et Uzès en 2026.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(409,1788530570789,'project','Adrien cherche aussi des pièces de carrosserie avant neuves pour la Ligier Xtoo afin de réaligner capot, ailes et fixations, ainsi qu''un écran LCD de compteur de remplacement.',0.78,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(410,1788530570815,'project','Le projet Y31 nécessite un accès pratique, l''organisation de barres à ruches, tonnes à eau, caravane et remorque fourgon laboratoire, tout en évitant dérive, pillage et vis-à-vis route fréquentée.',0.82,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(411,1788530570820,'fact','Pour Nîmes, la mairie a indiqué le 25 août 2026 qu''une cession est envisageable si le repreneur propose sensiblement les mêmes produits ; courrier du cédant, courrier du repreneur et dossier marché sont nécessaires.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets","date":"2026-08-25"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(412,1788530570836,'fact','Pour le ciel de toit de la Ligier Xtoo, Adrien a précisé qu''il est en carton rigide et collé, avec projet d''ajouter de la mousse pour rembourrage/insonorisation et refaire la zone du plafonnier.',0.67,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"ligier"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(413,1788530570867,'project','Un projet Agroof concerne des haies et plantes mellifères autour de la parcelle Y31.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"Y31"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(414,1788530570884,'fact','La commission des marchés de Nîmes était annoncée après la Féria, fin septembre 2026.',0.72,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"markets"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(415,1788530570890,'project','Adrien a un projet d''upgrade de PC jeu avec budget autour de 350 €, et a comparé notamment des configurations Ryzen 5 3600 + RTX 2060 / RX 5600 XT, avec objectif d''évolutivité.',0.74,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"pc"}');
