INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(420,1788530571007,'fact','Adrien utilise ou possède les domaines atelierdumeliturge.fr, rucherdumeliturge.fr, verite-interdite.fr et verite-interdite.com.',0.86,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"web"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(421,1788530571025,'project','Adrien a un dossier devant le tribunal administratif de Nîmes lié à un marché communal, référencé dans les échanges comme dossier 2601675, requête du 6 avril 2026. Toute synthèse future doit distinguer les faits documentés, les allégations d''Adrien et les réponses officielles.',0.88,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"private","topic":"legal"}');
