INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(426,1788530571141,'preference','Adrien veut faire évoluer ses sites vers un rendu plus professionnel, rassurant et orienté conversion, avec davantage d''outils gratuits, de contenu, de visibilité et une présentation plus lisible.',0.84,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"web"}');
INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(427,1788530571160,'fact','Adrien a engagé en 2026 des démarches personnelles autour d''un possible diagnostic TSA/CRA et souhaite que les informations médicales restent privées, contextualisées et jamais présentées comme un diagnostic définitif sans document médical.',0.9,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"high","topic":"health"}');
