INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(496,1788530572668,'preference','Adrien ne souhaite pas que des dépenses soient engagées sans autorisation. Pour MELITURGOS, privilégier les solutions gratuites ou à très faible coût tant que le budget est contraint.',0.99,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"budget"}');
