INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(499,1788530572732,'preference','Quand une solution peut être locale ou cloud, Adrien préfère une architecture hybride : mémoire/contrôle sous sa responsabilité et puissance distante ponctuelle si nécessaire.',0.92,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"architecture"}');
