INSERT INTO "memories_v021_snapshot" ("id","created_at","kind","content","importance","source","metadata") VALUES(502,1788530572799,'decision','Pour les changements importants de MELITURGOS, conserver une version stable, tester les versions candidates, mesurer les performances et prévoir un rollback avant promotion.',0.98,'import','{"genesis_version":"1.0","source":"shared_chat_history","sensitivity":"normal","topic":"self_improvement"}');
